func (this *Gate) CreateExpiredOptionMarket(symbol any) any {
	// support expired option contracts
	var quote string = "USDT"
	var settle any = quote
	var optionParts []string = Split(symbol, "-")
	var symbolBase []string = Split(symbol, "/")
	var marketIdBase []string = Split(symbol, "_")
	var base any = nil
	var expiry any = this.SafeString(optionParts, 1)
	if IsTrue(IsGreaterThan(GetIndexOf(symbol, "/"), OpNeg(1))) {
		base = this.SafeString(symbolBase, 0)
	} else {
		base = this.SafeString(marketIdBase, 0)
		expiry = Slice(expiry, 2, 8) // convert 20230728 to 230728
	}
	var strike any = this.SafeString(optionParts, 2)
	var optionType any = this.SafeString(optionParts, 3)
	var datetime any = this.ConvertExpireDate(expiry)
	var timestamp any = this.Parse8601(datetime)
	return map[string]any{
		"id":             Add(Add(Add(Add(Add(Add(Add(Add(Add(base, "_"), quote), "-"), "20"), expiry), "-"), strike), "-"), optionType),
		"symbol":         Add(Add(Add(Add(Add(Add(Add(Add(Add(Add(base, "/"), quote), ":"), settle), "-"), expiry), "-"), strike), "-"), optionType),
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         base,
		"quoteId":        quote,
		"settleId":       settle,
		"active":         false,
		"type":           "option",
		"linear":         nil,
		"inverse":        nil,
		"spot":           false,
		"swap":           false,
		"future":         false,
		"option":         true,
		"margin":         false,
		"contract":       true,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         timestamp,
		"expiryDatetime": datetime,
		"optionType":     Ternary(IsTrue((IsEqual(optionType, "C"))), "call", "put"),
		"strike":         this.ParseNumber(strike),
		"precision": map[string]any{
			"amount": this.ParseNumber("1"),
			"price":  nil,
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"info": nil,
	}
}
func (this *Gate) SafeMarket(optionalArgs ...any) any {
	marketId := GetArg(optionalArgs, 0, nil)
	_ = marketId
	market := GetArg(optionalArgs, 1, nil)
	_ = market
	delimiter := GetArg(optionalArgs, 2, nil)
	_ = delimiter
	marketType := GetArg(optionalArgs, 3, nil)
	_ = marketType
	var isOption bool = IsTrue((!IsEqual(marketId, nil))) && IsTrue((IsTrue((IsGreaterThan(GetIndexOf(marketId, "-C"), OpNeg(1)))) || IsTrue((IsGreaterThan(GetIndexOf(marketId, "-P"), OpNeg(1))))))
	if IsTrue(IsTrue(isOption) && IsTrue((IsTrue((IsEqual(this.Markets_by_id, nil))) || !IsTrue((InOp(this.Markets_by_id, marketId)))))) {
		// handle expired option contracts
		return this.CreateExpiredOptionMarket(marketId)
	}
	return this.Exchange.SafeMarket(marketId, market, delimiter, marketType)
}

/**
 * @method
 * @name gate#fetchMarkets
 * @description retrieves data on all markets for gate
 * @see https://www.gate.com/docs/developers/apiv4/#query-all-supported-currency-pairs                                       // spot
 * @see https://www.gate.com/docs/developers/apiv4/en/#list-all-supported-currency-pairs-supported-in-margin-trading         // margin
 * @see https://www.gate.com/docs/developers/apiv4/en/#query-all-futures-contracts                                           // swap
 * @see https://www.gate.com/docs/developers/apiv4/en/#query-all-futures-contracts-2                                         // future
 * @see https://www.gate.com/docs/developers/apiv4/en/#list-all-contracts-for-specified-underlying-and-expiration-date       // option
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Gate) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Gate) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	if IsTrue(IsEqual(GetValue(this.Options, "adjustForTimeDifference"), true)) {

		retRes138012 := (<-this.LoadTimeDifferenceAsync())
		PanicOnError(retRes138012)
	}
	if IsTrue(this.CheckRequiredCredentials(false)) {

		retRes138312 := (<-this.LoadUnifiedStatusAsync())
		PanicOnError(retRes138312)
	}
	var rawPromises any = []any{}
	var fetchMarketsOptions any = this.SafeDict(this.Options, "fetchMarkets")
	var types any = this.SafeList(fetchMarketsOptions, "types", []any{"spot", "swap", "future", "option"})
	for i := 0; IsLessThan(i, GetArrayLength(types)); i++ {
		var marketType any = GetValue(types, i)
		if IsTrue(IsEqual(marketType, "spot")) {
			// if (!sandboxMode) {
			// gate doesn't have a sandbox for spot markets
			AppendToArray(&rawPromises, this.FetchSpotMarketsAsync(params))
		} else if IsTrue(IsEqual(marketType, "swap")) {
			AppendToArray(&rawPromises, this.FetchSwapMarketsAsync(params))
		} else if IsTrue(IsEqual(marketType, "future")) {
			AppendToArray(&rawPromises, this.FetchFutureMarketsAsync(params))
		} else if IsTrue(IsEqual(marketType, "option")) {
			AppendToArray(&rawPromises, this.FetchOptionMarketsAsync(params))
		}
	}

	results := (<-promiseAll(rawPromises))
	PanicOnError(results)

	ch <- this.ArraysConcat(results)
	return nil
}
