	//         "long_users":191,
	//         "quanto_multiplier":"1",
	//         "funding_impact_value":"7000",
	//         "leverage_max":"50",
	//         "cross_leverage_default":"10",
	//         "risk_limit_max":"2500000",
	//         "maker_fee_rate":"-0.0001", // not actual value for regular users
	//         "taker_fee_rate":"0.00075", // not actual value for regular users
	//         "orders_limit":100,
	//         "trade_id":10376084,
	//         "orderbook_id":1203922859,
	//         "funding_cap_ratio":"1",
	//         "voucher_leverage":"0",
	//         "is_pre_market":false,
	//         "status":"trading", // or "suspend"
	//         "launch_time":1758124392,
	//         "enable_circuit_breaker":false,
	//         "funding_rate_limit":"0.02",
	//         "market_order_slip_ratio":"0.04",
	//         "market_order_size_max":"300000",
	//         "contract_type":""
	//    }
	//
	//  Delivery Futures
	//
	//    {
	//        "name": "BTC_USDT_20200814",
	//        "underlying": "BTC_USDT",
	//        "cycle": "WEEKLY",
	//        "type": "direct",
	//        "quanto_multiplier": "0.0001",
	//        "mark_type": "index",
	//        "last_price": "9017",
	//        "mark_price": "9019",
	//        "index_price": "9005.3",
	//        "basis_rate": "0.185095",
