func (this *Gate) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "id": "d33361395",
	//         "currency": "USDT_TRX",
	//         "address": "TErdnxenuLtXfnMafLbfappYdHtnXQ5U4z",
	//         "amount": "100",
	//         "txid": "ae9374de34e558562fe18cbb1bf9ab4d9eb8aa7669d65541c9fa2a532c1474a0",
	//         "timestamp": "1626345819",
	//         "status": "DONE",
	//         "memo": ""
	//     }
	//
	// withdraw
	//
	//     {
	//         "id":"w64413318",
	//         "currency":"usdt",
	//         "amount":"10150",
	//         "address":"0x0ab891497116f7f5532a4c2f4f7b1784488628e1",
	//         "memo":null,
	//         "status":"REQUEST",
	//         "chain":"eth",
	//         "withdraw_order_id":"",
	//         "fee_amount":"4.15000000"
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "id": "210496",
	//         "timestamp": "1542000000",
	//         "withdraw_order_id": "order_123456",
	//         "currency": "USDT",
	//         "address": "1HkxtBAMrA3tP5ENnYY2CZortjZvFDH5Cs",
	//         "txid": "128988928203223323290",
	//         "block_number": "41575382",
	//         "amount": "222.61",
	//         "fee": "0.01",
	//         "memo": "",
	//         "status": "DONE",
	//         "chain": "TRX"
	//     }
	//
	//     {
	//         "id": "w13389675",
	//         "currency": "USDT",
	//         "amount": "50",
	//         "address": "TUu2rLFrmzUodiWfYki7QCNtv1akL682p1",
	//         "memo": null
	//     }
	//
	//     {
	//         "currency":"usdt",
	//         "address":"0x01c0A9b7b4CdE774AF0f3E47CB4f1c2CCdBa0806",
	//         "amount":"1880",
	//         "chain":"eth"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var id any = this.SafeString(transaction, "id")
	var typeVar any = nil
	var amountString any = this.SafeString(transaction, "amount")
	if IsTrue(!IsEqual(id, nil)) {
		if IsTrue(IsEqual(GetValue(id, 0), "b")) {
			// GateCode handling
			typeVar = Ternary(IsTrue(Precise.StringGt(amountString, "0")), "deposit", "withdrawal")
			amountString = Precise.StringAbs(amountString)
		} else {
			typeVar = this.ParseTransactionType(GetValue(id, 0))
		}
	}
	var feeCostString any = this.SafeString2(transaction, "fee", "fee_amount")
	if IsTrue(IsEqual(typeVar, "withdrawal")) {
		amountString = Precise.StringSub(amountString, feeCostString)
	}
	var networkId any = this.SafeStringUpper(transaction, "chain")
	var currencyId any = this.SafeString(transaction, "currency")
	var code any = this.SafeCurrencyCode(currencyId)
	var txid any = this.SafeString(transaction, "txid")
	var rawStatus any = this.SafeString(transaction, "status")
	var status any = this.ParseTransactionStatus(rawStatus)
	var address any = this.SafeString(transaction, "address")
	var tag any = this.SafeString(transaction, "memo")
	var timestamp any = this.SafeTimestamp(transaction, "timestamp")
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"currency":    code,
		"amount":      this.ParseNumber(amountString),
		"network":     this.NetworkIdToCode(networkId, code),
		"address":     address,
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         tag,
		"tagTo":       nil,
		"tagFrom":     nil,
		"status":      status,
		"type":        typeVar,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"updated":     nil,
		"internal":    nil,
		"comment":     nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(feeCostString),
		},
	}
}

