	var stopLossPrice any = this.SafeValue(params, "stopLossPrice", triggerPrice)
	var takeProfitPrice any = this.SafeValue(params, "takeProfitPrice")
	var isStopLossOrder any = !IsEqual(stopLossPrice, nil)
