func (this *Gate) ParseSettlement(settlement any, market any) any {
	//
	// fetchSettlementHistory
	//
	//     {
	//         "time": 1685952000,
	//         "profit": "18.266806892718",
	//         "settle_price": "26826.68068927182",
	//         "fee": "0.040240021034",
	//         "contract": "BTC_USDT-20230605-25000-C",
	//         "strike_price": "25000"
	//     }
	//
	// fetchMySettlementHistory option
	//
	//     {
	//         "size": -1,
	//         "settle_profit": "0",
	//         "contract": "BTC_USDT-20220624-26000-C",
	//         "strike_price": "26000",
	//         "time": 1656057600,
	//         "settle_price": "20917.461281337048",
	//         "underlying": "BTC_USDT",
	//         "realised_pnl": "-0.00116042",
	//         "fee": "0"
	//     }
	//
	// fetchMySettlementHistory future
	//     {
	//         "time": 1548654951,
	//         "contract": "BTC_USDT",
	//         "size": 600,
	//         "leverage": "25",
	//         "margin": "0.006705256878",
	//         "entry_price": "3536.123",
	//         "settle_price": "3421.54",
	//         "profit": "-6.87498",
	//         "fee": "0.03079386"
	//     }
	//
	var timestamp any = this.SafeTimestamp(settlement, "time")
	var marketId any = this.SafeString(settlement, "contract")
	return map[string]any{
		"info":      settlement,
		"symbol":    this.SafeSymbol(marketId, market),
		"price":     this.SafeNumber(settlement, "settle_price"),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
}
func (this *Gate) ParseSettlements(settlements any, market any) any {
	//
	// fetchSettlementHistory
	//
	//     [
	//         {
	//             "time": 1685952000,
	//             "profit": "18.266806892718",
	//             "settle_price": "26826.68068927182",
	//             "fee": "0.040240021034",
	//             "contract": "BTC_USDT-20230605-25000-C",
	//             "strike_price": "25000"
	//         }
	//     ]
	//
	// fetchMySettlementHistory
	//
	//     [
	//         {
	//             "size": -1,
	//             "settle_profit": "0",
	//             "contract": "BTC_USDT-20220624-26000-C",
	//             "strike_price": "26000",
	//             "time": 1656057600,
	//             "settle_price": "20917.461281337048",
	//             "underlying": "BTC_USDT",
	//             "realised_pnl": "-0.00116042",
	//             "fee": "0"
	//         }
	//     ]
	//
	var result any = []any{}
	for i := 0; IsLessThan(i, GetArrayLength(settlements)); i++ {
		AppendToArray(&result, this.ParseSettlement(GetValue(settlements, i), market))
	}
	return result
}

