func (this *Gate) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	// spot
	//
	//     {
	//         "id": "123456",
	//         "time": 1547633726123,
	//         "currency": "BTC",
	//         "change": "1.03",
	//         "balance": "4.59316525194",
	//         "type": "margin_in"
	//     }
	//
	// margin
	//
	//     {
	//         "id": "123456",
	//         "time": "1547633726",
	//         "time_ms": 1547633726123,
	//         "currency": "BTC",
	//         "currency_pair": "BTC_USDT",
	//         "change": "1.03",
	//         "balance": "4.59316525194"
	//     }
	//
	// swap and future
	//
	//     {
	//         "time": 1682294400.123456,
	//         "change": "0.000010152188",
	//         "balance": "4.59316525194",
	//         "text": "ETH_USD:6086261",
	//         "type": "fee"
	//     }
	//
	// option
	//
	//     {
	//         "time": 1685594770,
	//         "change": "3.33",
	//         "balance": "29.87911771",
	//         "text": "BTC_USDT-20230602-26500-C:2611026125",
	//         "type": "prem"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var direction any = nil
	var amount any = this.SafeString(item, "change")
	if IsTrue(Precise.StringLt(amount, "0")) {
		direction = "out"
		amount = Precise.StringAbs(amount)
	} else {
		direction = "in"
	}
	var currencyId any = this.SafeString(item, "currency")
	currency = this.SafeCurrency(currencyId, currency)
	var typeVar any = this.SafeString(item, "type")
	var rawTimestamp any = this.SafeString(item, "time")
	var timestamp any = nil
	if IsTrue(IsGreaterThan(GetLength(rawTimestamp), 10)) {
		timestamp = ParseInt(rawTimestamp)
	} else {
		timestamp = Multiply(ParseInt(rawTimestamp), 1000)
	}
	var balanceString any = this.SafeString(item, "balance")
	var changeString any = this.SafeString(item, "change")
	var before any = this.ParseNumber(Precise.StringSub(balanceString, changeString))
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "id"),
		"direction":        direction,
		"account":          nil,
		"referenceAccount": nil,
		"referenceId":      nil,
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         this.SafeCurrencyCode(currencyId, currency),
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           before,
		"after":            this.SafeNumber(item, "balance"),
		"status":           nil,
		"fee":              nil,
	}, currency)
}
