/**
 * @method
 * @name gate#fetchUnderlyingAssets
 * @description fetches the market ids of underlying assets for a specific contract market type
 * @see https://www.gate.com/docs/developers/apiv4/en/#list-all-underlying-assets
 * @param {object} [params] exchange specific params
 * @param {string} [params.type] the contract market type, 'option', 'swap' or 'future', the default is 'option'
 * @returns {object[]} a list of [underlying assets]{@link https://docs.ccxt.com/?id=underlying-assets-structure}
 */
func (this *Gate) FetchUnderlyingAssets(params ...any) ([]string, error) {
	res := <-this.FetchUnderlyingAssetsAsync(params...)
	if IsError(res) {
		return nil, CreateReturnError(res)
	}
	return NewStringArray(res), nil
}

/**
 * @method
 * @name gate#fetchLiquidations
 * @description retrieves the public liquidations of a trading pair
 * @see https://www.gate.com/docs/developers/apiv4/en/#query-liquidation-order-history
 * @param {string} symbol unified CCXT market symbol
 * @param {int} [since] the earliest time in ms to fetch liquidations for
 * @param {int} [limit] the maximum number of liquidation structures to retrieve
 * @param {object} [params] exchange specific parameters for the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest liquidation
 * @returns {object} an array of [liquidation structures]{@link https://docs.ccxt.com/?id=liquidation-structure}
 */
func (this *Gate) FetchLiquidations(symbol string, options ...FetchLiquidationsOptions) ([]Liquidation, error) {

	opts := FetchLiquidationsOptionsStruct{}

	for _, opt := range options {
		opt(&opts)
	}

	var since *int64 = opts.Since

	var limit *int64 = opts.Limit

	var params *map[string]any = opts.Params
	res := <-this.FetchLiquidationsAsync(symbol, since, limit, params)
	if IsError(res) {
		return nil, CreateReturnError(res)
	}
	return NewLiquidationArray(res), nil
}

